typedef struct {
    int x;
    int y;
} Coordinate;

Coordinate point = {10, 20};
Coordinate *ptr_point;

// Assignment using Address-of Operator
ptr_point = &point;

// Accessing members via pointer
ptr_point->x = 5;
// point.x is now 5


volatile int sensor_data = 0;
volatile int *sensor_ptr;

// Pointer to a volatile variable address
sensor_ptr = &sensor_data;

void update_sensor(int value) {
    *sensor_ptr = value; // Direct memory write
}

update_sensor(42);


void modify(int *value) {
    *value *= 2;
}

int original = 5;

// Pass the address to allow modification
modify(&original);
// original is now 10
